SELECT COUNT(*) AS dish_scoop_config_rows
FROM public.scoop_config sc
WHERE EXISTS (
    SELECT 1 FROM public.dishes d
    WHERE LOWER(TRIM(d.dish_name)) = LOWER(TRIM(sc.scoop_item_name))
);
